import os
import tomllib
from dataclasses import dataclass, field
from typing import Any, Literal, Union

EnvType = Literal["int", "float", "bool", "str"]

@dataclass(frozen=True)
class EnvErrorKind:
    key: str
    expected: EnvType
    message: str

@dataclass(frozen=True)
class EnvErrorDetail:
    kind: EnvErrorKind
    value: Any = field(default=None)

@dataclass(frozen=True)
class EnvErrorData:
    errors: list[EnvErrorDetail] = field(default_factory=list)

@dataclass(frozen=True)
class EnvConfigError(Exception):
    errors: EnvErrorData = field(default_factory=EnvErrorData)
    def __str__(self):
        return "\n".join(f"{d.kind.key}: {d.kind.message}" for d in self.errors.errors)
